  }
  env[match[1].trim()] = value;
}

const check = (name) => {
  const value = env[name] || "";
  let host = "unparsed";
  let port = "";
  try {
    const parsed = new URL(value);
    host = parsed.hostname.includes("pooler.supabase.com")
      ? "pooler"
      : parsed.hostname.startsWith("db.")
        ? "direct-db"
        : "other";
    port = parsed.port || "default";
  } catch {
    host = "unparsed";
  }
  return {
    name,
    hasProdRef: value.includes("kshrgedtoxsiotgzrcru"),
    host,
    port,
  };
};

const probe = async (name) => {
  const info = check(name);
  if (!info.hasProdRef) return { ...info, reach: "skipped" };
  const parsed = new URL(env[name]);
  const reach = await new Promise((resolve) => {
    const socket = net.connect({
      host: parsed.hostname,
      port: Number(parsed.port || 5432),
    });
    const done = (result) => {
      socket.destroy();
      resolve(result);
    };
    socket.setTimeout(8000);
    socket.on("connect", () => done("ok"));
    socket.on("timeout", () => done("timeout"));
    socket.on("error", () => done("error"));
  });
  return { ...info, reach };
};

const results = [];
for (const name of ["DATABASE_URL", "DIRECT_URL"]) {
  results.push(await probe(name));
}
console.log(JSON.stringify(results));
